import json
from typing import Any, Dict

def _offers_of(obj):
    # V3.12 多商品：优先取 offers[] 数组；旧单品平面对象包装为 1 品（offer_seq=1）
    if not isinstance(obj, dict):
        return []
    offers = obj.get('offers')
    if isinstance(offers, list):
        out = []
        for i, o in enumerate(offers, start=1):
            if not isinstance(o, dict):
                continue
            e = dict(o)
            e.setdefault('offer_seq', i)
            out.append(e)
        return out
    return [obj]

async def main(args):
    raw = args.params['query_list']
    if not isinstance(raw, str):
        raw = json.dumps(raw, ensure_ascii=False)
    record_json = ''
    offer_id = ''
    req_id = ''
    try:
        arr = json.loads(raw)
        if isinstance(arr, list) and arr:
            first = arr[0]
            if isinstance(first, dict):
                record_json = str(first.get('result_json') or '')
                req_id = str(first.get('req_id') or '')
        elif isinstance(arr, dict):
            record_json = str(arr.get('result_json') or '')
            req_id = str(arr.get('req_id') or '')
    except Exception:
        record_json = ''
    if not record_json:
        record_json = raw
    offers = []
    try:
        inner = json.loads(record_json)
        if isinstance(inner, dict):
            if not req_id:
                req_id = str(inner.get('req_id') or '')
            offers = _offers_of(inner)
            if offers:
                offer_id = str(offers[0].get('offer_id') or offers[0].get('offerId') or '')
    except Exception:
        offers = []
    ret: Output = {
        "record_json": record_json,
        "req_id": req_id,
        "offer_id": offer_id,
        "offers": json.dumps(offers, ensure_ascii=False)
    }
    return ret

import json
import urllib.request
import urllib.parse
from typing import Any, Dict

NOTIFY_URL = 'http://172.30.8.52:6174/api/v1/appstore/audit/async/notify'

def _parse_sales(raw: Any) -> Dict[str, Any]:
    if isinstance(raw, dict):
        return raw
    s = str(raw or '').strip()
    if not s:
        return {}
    try:
        obj = json.loads(s)
        return obj if isinstance(obj, dict) else {}
    except Exception:
        return {}

async def main(args):
    p = args.params
    sales = _parse_sales(p.get('sales_id'))
    file_id = str(p.get('file_id') or '')
    request_ids = []
    first_request_id = ''
    for name, item in sales.items():
        info = item if isinstance(item, dict) else {}
        params = {'sales_id': str(info.get('offerId') or name),
                  'location': str(info.get('location', 0)),
                  'sheet_name': str(info.get('sheet_name') or '套餐')}
        if file_id:
            params['file_id'] = file_id
        url = NOTIFY_URL + '?' + urllib.parse.urlencode(params)
        req = urllib.request.Request(url, method='GET',
                                     headers={'Accept': 'application/json'})
        with urllib.request.urlopen(req, timeout=30) as http_resp:
            resp = json.loads(http_resp.read().decode('utf-8'))
        rid = str(resp.get('request_id') or resp.get('requestId') or '')
        if rid:
            request_ids.append(rid)
            if not first_request_id:
                first_request_id = rid
    ret: Output = {'request_id': first_request_id,
                   'requestIds': ','.join(request_ids)}
    return ret

import json
import urllib.request
from typing import Any, Dict

INSERT_URL = 'http://172.30.8.52:6174/api/v1/appstore/audit/result/insert'

def _parse_sales(raw: Any) -> Dict[str, Any]:
    if isinstance(raw, dict):
        return raw
    s = str(raw or '').strip()
    if not s:
        return {}
    try:
        obj = json.loads(s)
        return obj if isinstance(obj, dict) else {}
    except Exception:
        return {}

async def main(args):
    p = args.params
    sales = _parse_sales(p.get('sales_id'))
    file_id = str(p.get('file_id') or '')
    request_ids = [x for x in str(p.get('requestIds') or '').split(',') if x]
    result_code = '0'
    for idx, (name, item) in enumerate(sales.items()):
        info = item if isinstance(item, dict) else {}
        record = {'sales_id': str(info.get('offerId') or name),
                  'file_id': file_id,
                  'request_id': request_ids[idx] if idx < len(request_ids) else '',
                  'status': '1000'}
        body = json.dumps({'records': [record]}).encode('utf-8')
        req = urllib.request.Request(INSERT_URL, data=body, method='POST',
                                     headers={'Content-Type': 'application/json'})
        with urllib.request.urlopen(req, timeout=30) as http_resp:
            resp = json.loads(http_resp.read().decode('utf-8'))
        code = str(resp.get('resultCode', '0'))
        if code not in ('', '0'):
            result_code = code
    ret: Output = {'resultCode': result_code}
    return ret

import json
from typing import Any, Dict

def _roster_map(raw):
    # 权威名册归一：入参可为 [{offer_seq,name,quantity}] / {offers:[...]} / JSON 字符串
    obj = raw
    if isinstance(obj, str):
        try:
            obj = json.loads(obj)
        except Exception:
            obj = None
    if isinstance(obj, dict):
        obj = obj.get('offers')
    if not isinstance(obj, list):
        return {}
    out = {}
    for i, o in enumerate(obj, start=1):
        if not isinstance(o, dict):
            continue
        seq = str(o.get('offer_seq') if o.get('offer_seq') not in (None, '') else i)
        name = str(o.get('name') or '').strip()
        qty = o.get('quantity')
        if name or qty not in (None, ''):
            out[seq] = {'name': name, 'quantity': qty}
    return out

def _merge_roster(offers, raw):
    # 按 offer_seq 把权威名册的 name/quantity 合并进逐品元素（已有非空 name 不覆盖）
    roster = _roster_map(raw)
    if not roster or not isinstance(offers, list):
        return offers
    for i, o in enumerate(offers, start=1):
        if not isinstance(o, dict):
            continue
        seq = str(o.get('offer_seq') if o.get('offer_seq') not in (None, '') else i)
        r = roster.get(seq)
        if not r:
            continue
        if r.get('name') and not str(o.get('name') or '').strip():
            o['name'] = r['name']
        if r.get('quantity') not in (None, '') and o.get('quantity') in (None, ''):
            o['quantity'] = r['quantity']
    return offers

_PASSTHROUGH = ('pass', 'error_list', 'audit_summary', 'risk_list', 'compare_list',
                'requestIds', 'sales_id', 'file_id', 'globalId', 'testScenes', 'offer_id',
                'offers', 'req_id', 'plan_json', 'file_name', 'download_url')

def _any(v):
    if isinstance(v, (list, dict)):
        return v
    if v is None:
        return None
    s = str(v)
    if not s.strip():
        return None
    t = s.strip()
    if t[0] in '[{' and t[-1] in ']}':
        try:
            return json.loads(t)
        except Exception:
            return s
    return s

def _sales_lines(raw):
    # 清单 JSON（销售品名→{offerId,location,sheet_name}）→ 编号逐行文本
    obj = _any(raw)
    if not isinstance(obj, dict):
        return str(raw or '')
    lines = []
    for i, (name, item) in enumerate(obj.items(), start=1):
        info = item if isinstance(item, dict) else {}
        offer_id = str(info.get('offerId') or info.get('offer_id') or '')
        sheet = str(info.get('sheet_name') or '')
        lines.append('%d. %s（销售品ID=%s，Sheet=%s）' % (i, name, offer_id, sheet))
    return '\n'.join(lines)

async def main(args):
    p = args.params
    env: Dict[str, Any] = {}
    for key in _PASSTHROUGH:
        if key in p and p.get(key) is not None and str(p.get(key)) != '':
            env[key] = _any(p.get(key))
    # V3.14：按权威名册合并 name/quantity 进落库 offers[]（名册缺失时零变化）
    roster = p.get('roster') or p.get('roster_name') or ''
    if roster and isinstance(env.get('offers'), list):
        env['offers'] = _merge_roster(env['offers'], roster)
    md = str(p.get('md') or p.get('markdown') or '')
    md_key = str(p.get('md_key') or 'report_md')
    if md:
        env[md_key] = md
        env.setdefault('raw', md)
    file_id = str(p.get('file_id') or '')
    file_name = str(p.get('file_name') or '')
    download_url = str(p.get('download_url') or '')
    sales_list_text = _sales_lines(p.get('sales_id'))
    ret: Output = {
        'record_json': json.dumps(env, ensure_ascii=False),
        'file_id': file_id,
        'file_name': file_name,
        'download_url': download_url,
        'sales_list_text': sales_list_text
    }
    return ret

